<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { Grid, List, Plus, Search, Star } from '@element-plus/icons-vue'
import { materialApi, systemApi } from '../api'
import DynamicMaterialDrawer from '../components/module/DynamicMaterialDrawer.vue'
import { STATUS_LABELS } from '../config/materials'
import { useGenresStore } from '../stores/genres'
import type { Material, ModuleSection, Pagination } from '../types'
import { formatRelative } from '../utils/format'

const genreStore = useGenresStore()
const materials = ref<Material[]>([])
const allSections = ref<ModuleSection[]>([])
const pagination = reactive<Pagination>({ page: 1, page_size: 20, total: 0, pages: 0 })
const loading = ref(false)
const view = ref<'card'|'table'>('card')
const filters = reactive({ q: '', genre_module_id: [] as string[], section_id: [] as string[], status: [] as string[], tags: [] as string[], favorite: null as boolean|null, created_range: null as [string,string]|null, updated_range: null as [string,string]|null, sort: 'updated_desc' })
const drawerOpen = ref(false)
const drawerMode = ref<'view'|'edit'|'create'>('view')
const selected = ref<Material|null>(null)
let timer: number | undefined

const availableSections = computed(() => filters.genre_module_id.length ? allSections.value.filter((item) => filters.genre_module_id.includes(item.genre_module_id)) : allSections.value)
const activeFilterCount = computed(() => filters.genre_module_id.length + filters.section_id.length + filters.status.length + filters.tags.length + (filters.favorite !== null ? 1 : 0) + (filters.created_range ? 1 : 0) + (filters.updated_range ? 1 : 0))

async function load() {
  loading.value = true
  try {
    const params: Record<string, unknown> = { page: pagination.page, page_size: pagination.page_size, sort: filters.sort, deleted: 'active' }
    if (filters.q) params.q = filters.q
    for (const key of ['genre_module_id','section_id','status','tags'] as const) if (filters[key].length) params[key] = filters[key].join(',')
    if (filters.favorite !== null) params.favorite = filters.favorite
    if (filters.created_range) { params.created_from = `${filters.created_range[0]}T00:00:00`; params.created_to = `${filters.created_range[1]}T23:59:59` }
    if (filters.updated_range) { params.updated_from = `${filters.updated_range[0]}T00:00:00`; params.updated_to = `${filters.updated_range[1]}T23:59:59` }
    const response = await materialApi.list(params); materials.value = response.data.data.items; Object.assign(pagination, response.data.data.pagination)
  } finally { loading.value = false }
}

onMounted(async () => { const [, options] = await Promise.all([genreStore.fetchModules(), systemApi.options()]); allSections.value = (options.data.data.module_sections || []) as ModuleSection[]; await load() })
watch(filters, () => { if (timer) clearTimeout(timer); timer = window.setTimeout(() => { pagination.page = 1; void load() }, 300) }, { deep: true })
watch([() => pagination.page, () => pagination.page_size], () => void load())

function clearFilters() { Object.assign(filters, { q: '', genre_module_id: [], section_id: [], status: [], tags: [], favorite: null, created_range: null, updated_range: null, sort: 'updated_desc' }) }
function openCreate() { selected.value = null; drawerMode.value = 'create'; drawerOpen.value = true }
function openDetail(item: Material) { selected.value = item; drawerMode.value = 'view'; drawerOpen.value = true }
async function changed(item?: Material) { if (item) selected.value = item; await Promise.all([load(), genreStore.fetchModules()]) }
</script>

<template>
  <div class="all-page">
    <div class="page-heading"><div><span>CROSS-GENRE SEARCH</span><h1>全部素材</h1><p>跨题材、跨板块检索可复用的创作资产。</p></div><el-button type="primary" :icon="Plus" @click="openCreate">新增素材</el-button></div>
    <section class="search-hero surface"><div class="big-search"><el-icon><Search /></el-icon><input v-model="filters.q" placeholder="搜索标题、概述、正文、标签、自定义字段或题材模块…" /><kbd>300ms</kbd></div><div class="filter-line"><el-select v-model="filters.genre_module_id" multiple collapse-tags clearable placeholder="题材模块"><el-option v-for="item in genreStore.activeModules" :key="item.id" :label="item.name" :value="item.id" /></el-select><el-select v-model="filters.section_id" multiple collapse-tags clearable placeholder="功能板块"><el-option v-for="item in availableSections" :key="item.id" :label="item.section_name" :value="item.id" /></el-select><el-select v-model="filters.status" multiple collapse-tags clearable placeholder="素材状态"><el-option v-for="(label,value) in STATUS_LABELS" :key="value" :label="label" :value="value" /></el-select><el-select v-model="filters.tags" multiple collapse-tags allow-create filterable clearable placeholder="标签" /><el-select v-model="filters.favorite" clearable placeholder="收藏状态"><el-option label="已收藏" :value="true" /><el-option label="未收藏" :value="false" /></el-select><el-date-picker v-model="filters.created_range" type="daterange" value-format="YYYY-MM-DD" start-placeholder="创建开始" end-placeholder="创建结束" /><el-date-picker v-model="filters.updated_range" type="daterange" value-format="YYYY-MM-DD" start-placeholder="修改开始" end-placeholder="修改结束" /></div><button v-if="activeFilterCount" class="clear" @click="clearFilters">清空 {{ activeFilterCount }} 个筛选条件</button></section>
    <div class="results-bar"><div><h2>素材结果</h2><span>{{ pagination.total }} 条真实数据库记录</span></div><div><el-select v-model="filters.sort" class="sort"><el-option label="最近更新" value="updated_desc" /><el-option label="最新创建" value="created_desc" /><el-option label="使用最多" value="usage_desc" /><el-option label="标题正序" value="title_asc" /></el-select><div class="view-switch"><button :class="{active:view==='card'}" @click="view='card'"><el-icon><Grid /></el-icon></button><button :class="{active:view==='table'}" @click="view='table'"><el-icon><List /></el-icon></button></div></div></div>
    <div v-if="view==='card'" v-loading="loading" class="cross-grid"><article v-for="item in materials" :key="item.id" @click="openDetail(item)"><div class="card-top"><span class="module-badge" :style="{color:item.genre_module?.theme_color,borderColor:`color-mix(in srgb, ${item.genre_module?.theme_color} 50%, transparent)`}">{{ item.genre_module?.name }}</span><span>{{ item.section?.section_name }}</span><el-icon v-if="item.favorite"><Star /></el-icon></div><h3>{{ item.title }}</h3><p>{{ item.summary || '暂无概述' }}</p><div class="meta"><span v-for="(value,key) in Object.fromEntries(Object.entries(item.metadata).slice(0,2))" :key="key"><small>{{ key }}</small>{{ Array.isArray(value)?value.join('、'):String(value) }}</span></div><div class="tags"><i v-for="tag in item.tags.slice(0,3)" :key="tag.id">#{{ tag.name }}</i></div><footer><span>{{ STATUS_LABELS[item.status] }}</span><span>{{ formatRelative(item.updated_at) }}</span><span>用过 {{ item.usage_count }} 次</span></footer></article><div v-if="!loading&&!materials.length" class="empty"><h3>没有匹配的素材</h3><p>尝试减少筛选条件，或创建一条新的模块素材。</p><el-button @click="clearFilters">清空筛选</el-button></div></div>
    <el-table v-else v-loading="loading" :data="materials" class="material-table"><el-table-column label="素材" min-width="280"><template #default="scope"><div class="title-cell"><i :style="{background:scope.row.genre_module?.theme_color}"></i><div><b>{{ scope.row.title }}</b><small>{{ scope.row.summary }}</small></div></div></template></el-table-column><el-table-column label="题材模块" width="130"><template #default="scope">{{ scope.row.genre_module?.name }}</template></el-table-column><el-table-column label="功能板块" width="120"><template #default="scope">{{ scope.row.section?.section_name }}</template></el-table-column><el-table-column label="标签" min-width="160"><template #default="scope"><span class="table-tag" v-for="tag in scope.row.tags.slice(0,3)" :key="tag.id">#{{ tag.name }}</span></template></el-table-column><el-table-column label="状态" width="90"><template #default="scope">{{ STATUS_LABELS[scope.row.status] }}</template></el-table-column><el-table-column prop="usage_count" label="使用" width="75" /><el-table-column label="更新时间" width="100"><template #default="scope">{{ formatRelative(scope.row.updated_at) }}</template></el-table-column><el-table-column label="操作" width="80" fixed="right"><template #default="scope"><el-button text @click="openDetail(scope.row)">查看</el-button></template></el-table-column></el-table>
    <div class="pager"><el-pagination v-model:current-page="pagination.page" v-model:page-size="pagination.page_size" background layout="total,sizes,prev,pager,next" :page-sizes="[12,20,40,80]" :total="pagination.total" /></div>
    <DynamicMaterialDrawer v-model="drawerOpen" v-model:mode="drawerMode" :material="selected" @changed="changed" />
  </div>
</template>

<style scoped>
.all-page{max-width:1500px;margin:0 auto;padding:28px 30px 50px}.page-heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:20px}.page-heading span{color:var(--accent);font-size:8px;font-weight:800;letter-spacing:.16em}.page-heading h1{margin:5px 0 4px;font-family:"Songti SC",serif;font-size:27px}.page-heading p{margin:0;color:var(--text-muted);font-size:11px}.search-hero{position:relative;padding:15px;border-radius:10px}.big-search{height:44px;display:flex;align-items:center;gap:10px;padding:0 13px;border:1px solid var(--border);border-radius:8px;background:var(--bg-soft);color:var(--text-muted)}.big-search input{flex:1;border:0;outline:0;background:transparent;color:var(--text);font-size:12px}.big-search kbd{font-size:8px}.filter-line{display:grid;grid-template-columns:repeat(5,1fr) 1.5fr 1.5fr;gap:8px;margin-top:10px}.clear{position:absolute;right:15px;bottom:-24px;border:0;background:transparent;color:var(--accent);font-size:9px;cursor:pointer}.results-bar{display:flex;align-items:center;justify-content:space-between;margin:28px 0 11px}.results-bar>div{display:flex;align-items:center;gap:8px}.results-bar h2{margin:0;font-size:13px}.results-bar span{color:var(--text-muted);font-size:9px}.sort{width:110px}.view-switch{display:flex;padding:3px;border:1px solid var(--border);border-radius:7px;background:var(--panel)}.view-switch button{width:29px;height:25px;display:grid;place-items:center;border:0;border-radius:5px;background:transparent;color:var(--text-muted);cursor:pointer}.view-switch button.active{background:var(--panel-hover);color:var(--text)}.cross-grid{min-height:400px;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}.cross-grid article{min-height:245px;display:flex;flex-direction:column;padding:15px;border:1px solid var(--border-soft);border-radius:9px;background:var(--panel);cursor:pointer;transition:.18s}.cross-grid article:hover{transform:translateY(-2px);border-color:var(--border);background:var(--panel-raised)}.card-top{display:flex;align-items:center;gap:7px;color:var(--text-muted);font-size:8px}.card-top .module-badge{padding:3px 6px;border:1px solid;border-radius:4px;font-weight:700}.card-top>.el-icon{margin-left:auto;color:var(--accent)}.cross-grid h3{margin:14px 0 7px;font-family:"Songti SC",serif;font-size:16px}.cross-grid article>p{min-height:38px;margin:0;color:var(--text-secondary);font-size:10px;line-height:1.7;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.meta{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-top:10px}.meta span{padding:6px;overflow:hidden;border-radius:5px;background:var(--bg-soft);color:var(--text-secondary);font-size:8px;text-overflow:ellipsis;white-space:nowrap}.meta small{display:block;margin-bottom:3px;color:var(--text-muted);font-size:7px}.tags{display:flex;gap:4px;margin:10px 0}.tags i,.table-tag{padding:3px 5px;border-radius:4px;background:rgba(139,92,246,.1);color:#b7a0ee;font-size:8px;font-style:normal}.cross-grid footer{display:flex;gap:8px;margin-top:auto;padding-top:11px;border-top:1px solid var(--border-soft);color:var(--text-muted);font-size:8px}.cross-grid footer span:nth-child(2){margin-left:auto}.empty{grid-column:1/-1;display:grid;place-content:center;justify-items:center;border:1px dashed var(--border);border-radius:10px}.empty h3{margin:0}.empty p{color:var(--text-muted);font-size:10px}.material-table{border:1px solid var(--border-soft);border-radius:9px}.title-cell{display:flex;align-items:center;gap:9px}.title-cell>i{width:6px;height:28px;border-radius:3px}.title-cell b,.title-cell small{display:block}.title-cell b{color:var(--text);font-size:11px}.title-cell small{max-width:300px;margin-top:3px;overflow:hidden;color:var(--text-muted);font-size:8px;text-overflow:ellipsis;white-space:nowrap}.table-tag{margin-right:4px}.pager{display:flex;justify-content:center;padding-top:24px}@media(max-width:1250px){.cross-grid{grid-template-columns:repeat(3,1fr)}.filter-line{grid-template-columns:repeat(4,1fr)}}
</style>
